// Card illustration window (2.4.0): right-click a card in the bag (or "Inspect card" in the compound list) to see its picture,
// name and effect, like inspecting a card in RO. Pictures are generated by tools/art/card_sheets.py into public/art/cards/<itemId>.webp;
// a card without one shows a drawn placeholder (never a broken image). Items with `rarity: "legendary"` get a gold frame.
import "./cardart.css";
import { ITEMS } from "../../../shared/rules/items.ts";
import { cardEffectLines, cardGoesOn } from "../../../shared/rules/cards.ts";
import { MOB_BY_ID } from "../../../shared/rules/data.ts";
import { toggle } from "./windows.ts";

const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;

export function inspectCard(itemId: number) {
  const it = ITEMS.get(itemId);
  if (!it) return;
  const legendary = (it as { rarity?: string }).rarity === "legendary";
  const win = $("w-cardart");
  win.classList.toggle("legendary", legendary);
  $("ca-title").textContent = legendary ? "Legendary Card" : "Card";
  const img = $<HTMLImageElement>("ca-img");
  const fb = $("ca-fallback");
  img.hidden = false; fb.hidden = true;
  img.onerror = () => { img.hidden = true; fb.hidden = false; fb.textContent = it.name.replace(" Card", "").slice(0, 1); };
  img.src = `/art/cards/${itemId}.webp`;
  const mob = it.mobId ? MOB_BY_ID.get(it.mobId) : undefined;
  const text = $("ca-text");
  text.innerHTML = "";
  const add = (tag: string, cls: string, t: string) => text.append(Object.assign(document.createElement(tag), { className: cls, textContent: t }));
  add("b", "ca-name", it.name);
  add("div", "ca-where", `Compound on: ${cardGoesOn(it)}`);
  for (const l of cardEffectLines(it)) add("div", "ca-fx", l);
  if (mob) add("div", "ca-mob", `${mob.name} · Lv ${mob.level} · ${mob.race} · ${mob.element}`);
  toggle(win, true);
}
